/**
 * Paths and constants shared by the Playwright config, global setup and specs.
 *
 * Playwright evaluates the config in the runner AND in every worker; the run id is put in
 * the environment on first evaluation so all processes agree on one temp directory.
 */
import { tmpdir } from 'node:os'
import path from 'node:path'

process.env.RF_E2E_RUN ??= `${Date.now()}-${process.pid}`

export const E2E_DIR = path.join(tmpdir(), `reelforge-e2e-${process.env.RF_E2E_RUN}`)
/** REELFORGE_DATA of the server under test. */
export const E2E_DATA = path.join(E2E_DIR, 'data')
/** Media generated by global setup (lavfi), uploaded by the specs. */
export const E2E_FIXTURES = path.join(E2E_DIR, 'fixtures')
export const SAMPLE_VIDEO = path.join(E2E_FIXTURES, 'sample-vertical.mp4')
/** Duration of SAMPLE_VIDEO in seconds. */
export const SAMPLE_SECONDS = 3

/** Fixed pairing code the server accepts when REELFORGE_TEST_PAIR_CODE is set. */
export const E2E_PAIR_CODE = '246810'

export const HTTPS_PORT = Number(process.env.RF_E2E_HTTPS_PORT ?? 18443)
export const HTTP_PORT = Number(process.env.RF_E2E_HTTP_PORT ?? 18080)
export const BASE_URL = `https://localhost:${HTTPS_PORT}`
